  "pass_consecrated_desc": {
    en: 'Your covenant is sealed on Solana. 333 SKR accepted (33% burned, 33% to Treasury, 34% to ORE staking). You now have +5 sacred spreads every day.',
    zh: '\u60A8\u7684\u5951\u7EA6\u5DF2\u5728 Solana \u4E0A\u786E\u8BA4\u3002\u5DF2\u6536\u5230 333 SKR\uFF0833% 销毁，33% 进入金库，34% 进入 ORE 质押\uFF09\u3002\u60A8\u73B0\u5728\u6BCF\u5929\u53EF\u989D\u5916\u4F7F\u7528 +5 \u6B21\u5360\u535C\u3002',
    hi: '\u0906\u092A\u0915\u093E \u0905\u0928\u0941\u092C\u0902\u0927 Solana \u092A\u0930 \u0938\u0941\u0930\u0915\u094D\u0937\u093F\u0924 \u0939\u0948\u0964 333 SKR \u0938\u094D\u0935\u0940\u0915\u093E\u0930 \u0915\u093F\u090F \u0917\u090F (50% \u0928\u0937\u094D\u091F, 50% \u0916\u091C\u093E\u0928\u0947 \u092E\u0947\u0902)\u0964 \u0905\u092C \u0906\u092A\u0915\u094B \u0939\u0930 \u0926\u093F\u0928 +5 \u092A\u0935\u093F\u0924\u094D\u0930 \u092A\u094D\u0930\u0936\u094D\u0928 \u092E\u093F\u0932\u0947\u0902\u0917\u0947\u0964',
    es: 'Tu pacto est\u00E1 sellado en Solana. 333 SKR aceptados (33% quemado, 33% al Tesoro, 34% a staking ORE). Ahora tienes +5 tiradas sagradas cada d\u00EDa.',
    ar: '\u062A\u0645 \u062A\u0648\u062B\u064A\u0642 \u0639\u0647\u062F\u0643 \u0639\u0644\u0649 Solana. \u062A\u0645 \u0642\u0628\u0648\u0644 333 SKR (50% \u062D\u0631\u0642\u060C 50% \u0644\u0644\u062E\u0632\u064A\u0646\u0629). \u0644\u062F\u064A\u0643 \u0627\u0644\u0622\u0646 +5 \u0642\u0631\u0627\u0621\u0627\u062A \u0645\u0642\u062F\u0633\u0629 \u0643\u0644 \u064A\u0648\u0645.',
    fr: 'Votre pacte est scell\u00E9 sur Solana. 333 SKR accept\u00E9s (33% brûlés, 33% au Trésor, 34% au staking ORE). Vous disposez d\u00E9sormais de +5 tirages sacr\u00E9s par jour.',
    bn: '\u0986\u09AA\u09A8\u09BE\u09B0 \u099A\u09C1\u0995\u09CD\u09A4\u09BF Solana-\u09A4\u09C7 \u09B8\u09BF\u09B2 \u0995\u09B0\u09BE \u09B9\u09AF\u09BC\u09C7\u099B\u09C7\u0964 333 SKR \u0997\u09C3\u09B9\u09C0\u09A4 (50% \u09AA\u09CB\u09DC\u09BE\u09A8\u09CB, 50% \u0995\u09CB\u09B7\u09BE\u0997\u09BE\u09B0\u09C7)\u0964 \u0986\u09AA\u09A8\u09BF \u098F\u0996\u0988 \u09AA\u09CD\u09B0\u09A4\u09BF\u09A6\u09BF\u09A8 +5\u099F\u09BF \u09AA\u09AC\u09BF\u09A4\u09CD\u09B0 \u09B0\u09BF\u09A1\u09BF\u0982 \u09AA\u09BE\u09AC\u09C7\u09A8\u0964',
    pt: 'Seu pacto est\u00E1 selado na Solana. 333 SKR aceitos (33% queimados, 33% para o Tesouro, 34% para staking ORE). Voc\u00EA agora tem +5 tiragens sagradas todos os dias.',
    ru: '\u0417\u0430\u0432\u0435\u0442 \u0441\u043A\u0440\u0435\u043F\u043B\u0435\u043D \u0432 Solana. 333 SKR \u043F\u0440\u0438\u043D\u044F\u0442\u044B (33% сожжено, 33% в казну, 34% в ORE стейкинг). \u0412\u0430\u043C \u0434\u043E\u0441\u0442\u0443\u043F\u043D\u043E +5 \u0441\u0432\u044F\u0449\u0435\u043D\u043D\u044B\u0445 \u0440\u0430\u0441\u043A\u043B\u0430\u0434\u043E\u0432 \u0435\u0436\u0435\u0434\u043D\u0435\u0432\u043D\u043E.',
    id: 'Perjanjian Anda telah disegel di Solana. 333 SKR diterima (33% dibakar, 33% ke Kas, 34% ke staking ORE). Anda sekarang menerima +5 tebaran suci setiap hari.',
  },
