    en: 'You can still read the cards you have drawn and consult your saved codex. On-chain draws resume when you are reconnected.',
    zh: '\u4F60\u4ECD\u53EF\u67E5\u9605\u5DF2\u89E3\u9501\u7684\u5361\u724C\u4E0E\u5171\u8BC6\u5178\u7C4D\u3002\u91CD\u65B0\u8054\u7F51\u540E\u5373\u53EF\u6062\u590D\u4E0A\u94FE\u62BD\u724C\u3002',
    hi: '\u0906\u092A \u0905\u092D\u0940 \u092D\u0940 \u0905\u092A\u0928\u0947 \u0916\u0941\u0932\u0947 \u0939\u0941\u090F \u0915\u093E\u0930\u094D\u0921 \u092A\u0922\u093C \u0938\u0915\u0924\u0947 \u0939\u0948\u0902\u0964 \u0915\u0928\u0947\u0915\u094D\u0936\u0928 \u0935\u093E\u092A\u0938 \u0906\u0928\u0947 \u092A\u0930 \u0911\u0928-\u091A\u0947\u0928 \u0921\u094D\u0930\u0949 \u092B\u093F\u0930 \u0936\u0941\u0930\u0942 \u0939\u094B\u0917\u093E\u0964',
    es: 'Puedes seguir consultando tus cartas descubiertas y el códex. Las tiradas on-chain se reanudarán al reconectar.',
    ar: '\u0644\u0627 \u064A\u0632\u0627\u0644 \u0628\u0625\u0645\u0643\u0627\u0646\u0643 \u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0628\u0637\u0627\u0642\u0627\u062A \u0627\u0644\u0645\u0641\u062A\u0648\u062D\u0629 \u0648\u062A\u0635\u0641\u062D \u0627\u0644\u0633\u062C\u0644. \u062A\u0633\u062A\u0623\u0646\u0641 \u0627\u0644\u0633\u062D\u0648\u0628\u0627\u062A \u0639\u0646\u062F \u0639\u0648\u062F\u0629 \u0627\u0644\u0627\u062A\u0635\u0627\u0644.',
    fr: 'Vous pouvez toujours consulter vos cartes dévoilées et votre codex. Les tirages on-chain reprendront dès la reconnexion.',
    bn: '\u0986\u09AA\u09A8\u09BF \u098F\u0996\u09A8\u0993 \u0989\u09A8\u09CD\u09AE\u09C1\u0995\u09CD\u09A4 \u0995\u09BE\u09B0\u09CD\u09A1 \u0993 \u0995\u09CB\u09A1\u09C7\u0995\u09CD\u09B8 \u09A6\u09C7\u0996\u09A4\u09C7 \u09AA\u09BE\u09B0\u09AC\u09C7\u09A8\u0964 \u09B8\u0982\u09AF\u09CB\u0997 \u09AB\u09BF\u09B0\u09B2\u09C7 \u0985\u09A8-\u099A\u09C7\u09A8 \u099F\u09BE\u09A8 \u09A4\u09BE\u09B2\u09C1 \u09B9\u09AC\u09C7\u0964',
    pt: 'Você ainda pode ler as cartas reveladas e consultar o códex. As tiragens on-chain retornam quando reconectar.',
    ru: '\u0412\u044B \u043F\u043E-\u043F\u0440\u0435\u0436\u043D\u0435\u043C\u0443 \u043C\u043E\u0436\u0435\u0442\u0435 \u0438\u0437\u0443\u0447\u0430\u0442\u044C \u043E\u0442\u043A\u0440\u044B\u0442\u044B\u0435 \u043A\u0430\u0440\u0442\u044B \u0438 \u043A\u043E\u043B\u043E\u0434\u0443. \u0421\u0435\u0442\u0435\u0432\u044B\u0435 \u0440\u0430\u0441\u043A\u043B\u0430\u0434\u044B \u0432\u043E\u0437\u043E\u0431\u043D\u043E\u0432\u044F\u0442\u0441\u044F \u043F\u0440\u0438 \u043F\u043E\u0434\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0438.',
