    fr: 'Les cartes se d\u00E9bloquent lorsque vous les tirez : un registre, pas un catalogue.',
    bn: '\u0995\u09BE\u09B0\u09CD\u09A1\u0997\u09C1\u09B2\u09BF \u0986\u0981\u0995\u09BE\u09B0 \u09B8\u09BE\u09A5\u09C7 \u09B8\u09BE\u09A5\u09C7 \u0986\u09A8\u09B2\u0995 \u09B9\u09AF\u09BC: \u098F\u0995\u099F\u09BF \u09B0\u09C7\u0995\u09B0\u09CD\u09A1, \u0995\u09CD\u09AF\u09BE\u099F\u09BE\u09B2\u0997 \u09A8\u09AF\u09BC\u0964',
    pt: 'As cartas desbloqueiam ao serem tiradas: um registro vivo, n\u00E3o um cat\u00E1logo.',
    ru: '\u0410\u0440\u043A\u0430\u043D\u044B \u043F\u0440\u043E\u0431\u0443\u0436\u0434\u0430\u044E\u0442\u0441\u044F, \u043A\u043E\u0433\u0434\u0430 \u0432\u044B \u0438\u0445 \u043E\u0442\u043A\u0440\u044B\u0432\u0430\u0435\u0442\u0435: \u0436\u0438\u0432\u0430\u044F \u043B\u0435\u0442\u043E\u043F\u0438\u0441\u044C, \u0430 \u043D\u0435 \u0441\u0443\u0445\u043E\u0439 \u043A\u0430\u0442\u0430\u043B\u043E\u0433.',
