  "streak_rewards_explanation": {
    en: 'Bonus spreads are permanently credited to your account for daily ritual milestones (7d: +1, 14d: +2, 21d: +3, 28d: +5, and +5 every 7 days thereafter). They never expire and are used whenever your daily free allowance is exhausted.',
    zh: '\u8FDE\u7EED\u65E5\u5E38\u4EEA\u5F0F\u7684\u91CC\u7A0B\u7891\u5956\u52B1\uFF087\u5929: +1, 14\u5929: +2, 21\u5929: +3, 28\u5929: +5\uFF0C\u6B64\u540E\u6BCF7\u5929 +5\uFF09\u5C06\u6C38\u4E45\u5B58\u5165\u60A8\u7684\u8D26\u6237\uFF0C\u6C38\u4E0D\u8FC7\u671F\uFF0C\u5E76\u5728\u6BCF\u65E5\u514D\u8D39\u989D\u5EA6\u7528\u5C3D\u540E\u81EA\u52A8\u4F7F\u7528\u3002',
    hi: '\u0926\u0948\u0928\u093F\u0915 \u0905\u0928\u0941\u0937\u094D\u0920\u093E\u0928 \u0915\u0947 \u092E\u0940\u0932 \u0915\u0947 \u092A\u0924\u094D\u0925\u0930\u094B\u0902 (7\u0926\u093F\u0928: +1, 14\u0926\u093F\u0928: +2, 21\u0926\u093F\u0928: +3, 28\u0926\u093F\u0928: +5 \u0914\u0930 \u0909\u0938\u0915\u0947 \u092C\u093E\u0926 \u092A\u094D\u0930\u0924\u094D\u092F\u0947\u0915 7 \u0926\u093F\u0928 \u092E\u0947\u0902 +5) \u0915\u0947 \u0932\u093F\u090F \u092C\u094B\u0928\u0938 \u0938\u094D\u092A\u094D\u0930\u0947\u0921 \u0938\u0926\u0948\u0935 \u0916\u093E\u0924\u0947 \u092E\u0947\u0902 \u0938\u0902\u091A\u093F\u0924 \u0930\u0939\u0924\u0947 \u0939\u0948\u0902\u0964 \u0926\u0948\u0928\u093F\u0915 \u0915\u094B\u091F\u093E \u0938\u092E\u093E\u092A\u094D\u0924 \u0939\u094B\u0928\u0947 \u092A\u0930 \u0907\u0928\u0915\u093E \u0909\u092A\u092F\u094B\u0917 \u0939\u094B\u0924\u093E \u0939\u0948\u0964',
    es: 'Las tiradas de bonificación se acreditan de forma permanente a tu cuenta al alcanzar hitos de racha (7d: +1, 14d: +2, 21d: +3, 28d: +5 y +5 cada 7 días posteriores). No caducan y se utilizan cuando se agota tu cuota diaria gratuita.',
    ar: '\u064A\u062A\u0645 \u0625\u0636\u0627\u0641\u0629 \u0627\u0644\u0633\u062D\u0648\u0628\u0627\u062A \u0627\u0644\u0645\u062C\u0627\u0646\u064A\u0629 \u062F\u0627\u0626\u0645\u0627\u064B \u0625\u0644\u0649 \u062D\u0633\u0627\u0628\u0643 \u0639\u0646\u062F \u062A\u062D\u0642\u064A\u0642 \u0645\u0631\u0627\u062D\u0644 \u0627\u0644\u062A\u062A\u0627\u0628\u0639 (7 \u0623\u064A\u0627\u0645: +1\u060C 14 \u064A\u0648\u0645\u0627\u064B: +2\u060C 21 \u064A\u0648\u0645\u0627\u064B: +3\u060C 28 \u064A\u0648\u0645\u0627\u064B: +5\u060C \u0648+5 \u0643\u0644 7 \u0623\u064A\u0627\u0645 \u0628\u0639\u062F \u0630\u0644\u0643). \u0644\u0627 \u062A\u0646\u062A\u0647\u064A \u0635\u0644\u0627\u062D\u064A\u062A\u0647\u0627 \u0648\u062A\u064F\u0633\u062A\u062E\u062F\u0645 \u0628\u0639\u062F \u0646\u0641\u0627\u062F \u0627\u0644\u062D\u0635\u0629 \u0627\u0644\u064A\u0648\u0645\u064A\u0629.',
    fr: 'Les tirages bonus sont crédités de façon permanente sur votre compte lors des jalons de série (7j : +1, 14j : +2, 21j : +3, 28j : +5 et +5 tous les 7 jours suivants). Ils n\'expirent jamais et sont utilisés lorsque le quota quotidien gratuit est épuisé.',
    bn: '\u09A6\u09C8\u09A8\u09BF\u0995 \u09B0\u09BF\u099A\u09C1\u09AF\u09BC\u09BE\u09B2\u09C7\u09B0 \u09AE\u09BE\u0987\u09B2\u09B8\u09CD\u099F\u09CB\u09A8\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF (7\u09A6\u09BF\u09A8: +1, 14\u09A6\u09BF\u09A8: +2, 21\u09A6\u09BF\u09A8: +3, 28\u09A6\u09BF\u09A8: +5, \u098F\u09AC\u0982 \u09AA\u09B0\u09AC\u09B0\u09CD\u09A4\u09C0 \u09AA\u09CD\u09B0\u09A4\u09BF 7 \u09A6\u09BF\u09A8\u09C7 +5) \u09AC\u09CB\u09A8\u09BE\u09B8 \u09B8\u09CD\u09AA\u09CD\u09B0\u09C7\u09A1\u0997\u09C1\u09B2\u09BF \u09B8\u09CD\u09A5\u09BE\u09AF\u09BC\u09C0\u09AD\u09BE\u09AC\u09C7 \u0986\u0995\u09BE\u0989\u09A8\u09CD\u099F\u09C7 \u09A5\u09BE\u0995\u09C7\u0964 \u09A6\u09C8\u09A8\u09BF\u0995 \u0995\u09CB\u099F\u09BE \u09B6\u09C7\u09B7 \u09B9\u09B2\u09C7 \u098F\u0997\u09C1\u09B2\u09BF \u09AC\u09CD\u09AF\u09AC\u09B9\u09BE\u09B0 \u09B9\u09AF\u09BC\u0964',
    pt: 'As tiradas bônus são creditadas permanentemente em sua conta pelos marcos de sequência ritual (7d: +1, 14d: +2, 21d: +3, 28d: +5 e +5 a cada 7 dias seguintes). Elas nunca expiram e são usadas quando sua cota diária gratuita se esgota.',
    ru: 'Бонусные расклады начисляются на ваш счет за рубежи ежедневного стрика (7д: +1, 14д: +2, 21д: +3, 28д: +5 и далее +5 каждые 7 дней непрерывного стрика). Они хранятся бессрочно и расходуются после исчерпания ежедневных бесплатных раскладов.',
    id: 'Spread bonus dikreditkan secara permanen ke akun Anda untuk pencapaian streak ritual harian (7h: +1, 14h: +2, 21h: +3, 28h: +5, dan +5 setiap 7 hari berikutnya). Tidak pernah kedaluwarsa dan digunakan saat kuota gratis harian habis.',
  },
