    zh: '\u672A\u627E\u5230\u539F\u578B',
    hi: '\u0915\u094B\u0908 \u092E\u0942\u0932\u0930\u0942\u092A \u0928\u0939\u0940\u0902 \u092E\u093F\u0932\u093E',
