  "no_archetypes_sub": {
    en: 'The Consensus found no cards matching your query.',
    zh: '\u5171\u8BC6\u672A\u627E\u5230\u4E0E\u60A8\u67E5\u8BE2\u5339\u914D\u7684\u5361\u724C\u3002',
    hi: '\u0938\u0930\u094D\u0935\u0938\u092E\u094D\u092E\u0924\u093F \u0915\u094B \u0906\u092A\u0915\u0947 \u092A\u094D\u0930\u0936\u094D\u0928 \u0938\u0947 \u092E\u0947\u0932 \u0916\u093E\u0924\u093E \u0915\u094B\u0908 \u0915\u093E\u0930\u094D\u0921 \u0928\u0939\u0940\u0902 \u092E\u093F\u0932\u093E\u0964',
    es: 'El Consenso no encontr\u00F3 cartas que coincidan con tu b\u00FAsqueda.',
    ar: '\u0644\u0645 \u064A\u062C\u062F \u0627\u0644\u0625\u062C\u0645\u0627\u0639 \u0623\u064A \u0628\u0637\u0627\u0642\u0627\u062A \u062A\u0637\u0627\u0628\u0642 \u0627\u0633\u062A\u0639\u0644\u0627\u0645\u0643.',
    fr: 'Le Consensus n\u2019a trouv\u00E9 aucune carte correspondant \u00E0 votre requ\u00EAte.',
    bn: '\u0990\u0995\u09AE\u09A4\u09CD\u09AF \u0986\u09AA\u09A8\u09BE\u09B0 \u0985\u09A8\u09C1\u09B8\u09A8\u09CD\u09A7\u09BE\u09A8\u09C7\u09B0 \u09B8\u09BE\u09A5\u09C7 \u09AE\u09C7\u09B2\u09C7 \u098F\u09AE\u09A8 \u0995\u09CB\u09A8\u09CB \u0995\u09BE\u09B0\u09CD\u09A1 \u0996\u09C1\u0981\u099C\u09C7 \u09AA\u09BE\u09AF\u09BC\u09A8\u09BF\u0964',
    pt: 'O Consenso n\u00E3o encontrou cartas correspondentes \u00E0 sua busca.',
    ru: '\u041A\u043E\u043D\u0441\u0435\u043D\u0441\u0443\u0441 \u043D\u0435 \u043E\u0431\u043D\u0430\u0440\u0443\u0436\u0438\u043B \u0430\u0440\u043A\u0430\u043D\u043E\u0432 \u043F\u043E \u0437\u0430\u043F\u0440\u043E\u0441\u0443.',
    id: 'Konsensus tidak menemukan kartu yang cocok dengan permintaan Anda.',
  },
