    zh: '\u4F60\u5C06\u5411\u8D26\u672C\u5448\u4E0A\u4F55\u79CD\u7591\u95EE\uFF1F',
    hi: '\u0906\u092A \u092C\u0939\u0940\u0916\u093E\u0924\u0947 \u0915\u0947 \u0938\u092E\u0915\u094D\u0937 \u0915\u094D\u092F\u093E \u092A\u094D\u0930\u0936\u094D\u0928 \u092A\u094D\u0930\u0938\u094D\u0924\u0941\u0924 \u0915\u0930\u0924\u0947 \u0939\u0948\u0902?',
