  "quota_modal_kicker": {
    en: 'CONSENSUS QUOTA \u00B7 3/3 USED TODAY',
    zh: '\u5171\u8BC6\u914D\u989D \u00B7 \u4ECA\u65E5 3/3 \u5DF2\u7528\u5C3D',
    hi: '\u0938\u0939\u092E\u0924\u093F \u0915\u094B\u091F\u093E \u00B7 \u0906\u091C 3/3 \u0909\u092A\u092F\u094B\u0917 \u0915\u093F\u092F\u093E \u0917\u092F\u093E',
    es: 'CUOTA DE CONSENSO \u00B7 3/3 USADAS HOY',
    ar: '\u062D\u0635\u0629 \u0627\u0644\u0625\u062C\u0645\u0627\u0639 \u00B7 \u062A\u0645 \u0627\u0633\u062A\u062E\u062F\u0627\u0645 3/3 \u0627\u0644\u064A\u0648\u0645',
    fr: 'QUOTA DE CONSENSUS \u00B7 3/3 UTILIS\u00C9S AUJOURD\'HUI',
    bn: '\u0990\u0995\u09AE\u09A4\u09CD\u09AF \u0995\u09CB\u099F\u09BE \u00B7 \u0986\u099C 3/3 \u09AC\u09CD\u09AF\u09AC\u09B9\u09C3\u09A4 \u09B9\u09AF\u09BC\u09C7\u099B\u09C7',
    pt: 'COTA DE CONSENSO \u00B7 3/3 USADAS HOJE',
    ru: '\u041B\u0418\u041C\u0418\u0422 \u041A\u041E\u041D\u0421\u0415\u041D\u0421\u0423\u0421\u0410 \u00B7 3/3 \u0418\u0421\u0427\u0415\u0420\u041F\u0410\u041D\u041E',
    id: 'KUOTA KONSENSUS \u00B7 3/3 DIGUNAKAN HARI INI',
  },
  "quota_veil_drawn_desc": {
    en: 'You have exhausted the 3 sacred inquiries granted to you by the ledger today.\n\nThe cards now require an offering of energy to part the veil once more. Will you commune now, or return tomorrow when the next UTC block seals?',
    zh: '\u60A8\u5DF2\u7528\u5C3D\u8D26\u672C\u4ECA\u65E5\u8D50\u4E88\u7684 3 \u6B21\u795E\u5723\u6C42\u95EE\u3002\n\n\u82E5\u60F3\u518D\u6B21\u6380\u5F00\u5E37\u5E55\uFF0C\u724C\u7EC4\u9700\u8981\u80FD\u91CF\u4F9B\u5949\u3002\u60A8\u662F\u73B0\u5728\u901A\u7075\uFF0C\u8FD8\u662F\u5F85\u660E\u65E5\u65B0\u7684 UTC \u533A\u5757\u5C01\u5370\u540E\u518D\u6765\uFF1F',
    hi: '\u0906\u092A\u0928\u0947 \u0906\u091C \u092C\u0939\u0940\u0916\u093E\u0924\u0947 \u0926\u094D\u0935\u093E\u0930\u093E \u0926\u093F\u090F \u0917\u090F 3 \u092A\u0935\u093F\u0924\u094D\u0930 \u092A\u094D\u0930\u0936\u094D\u0928\u094B\u0902 \u0915\u094B \u0938\u092E\u093E\u092A\u094D\u0924 \u0915\u0930 \u0926\u093F\u092F\u093E \u0939\u0948\u0964\n\n\u0915\u093E\u0930\u094D\u0921\u094D\u0938 \u0915\u094B \u092B\u093F\u0930 \u0938\u0947 \u092A\u0930\u094D\u0926\u093E \u0939\u091F\u093E\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u090A\u0930\u094D\u091C\u093E \u0915\u0940 \u092D\u0947\u0902\u091F \u0915\u0940 \u0906\u0935\u0936\u094D\u092F\u0915\u0924\u093E \u0939\u0948\u0964 \u0915\u094D\u092F\u093E \u0906\u092A \u0905\u092D\u0940 \u092C\u093E\u0924 \u0915\u0930\u0947\u0902\u0917\u0947, \u092F\u093E \u0915\u0932 \u0905\u0917\u0932\u0947 UTC \u092C\u094D\u0932\u0949\u0915 \u092A\u0930 \u0932\u094C\u091F\u0947\u0902\u0917\u0947?',
    es: 'Has agotado las 3 consultas sagradas otorgadas por el registro hoy.\n\nLas cartas ahora requieren una ofrenda de energ\u00EDa para descorrer el velo. \u00BFComulgar\u00E1s ahora o volver\u00E1s ma\u00F1ana con el pr\u00F3ximo bloque UTC?',
    ar: '\u0644\u0642\u062F \u0627\u0633\u062A\u0646\u0641\u062F\u062A \u0627\u0644\u0627\u0633\u062A\u0641\u0633\u0627\u0631\u0627\u062A \u0627\u0644\u0645\u0642\u062F\u0633\u0629 \u0627\u0644\u062B\u0644\u0627\u062B\u0629 \u0627\u0644\u0645\u0645\u0646\u0648\u062D\u0629 \u0644\u0643 \u0645\u0646 \u0627\u0644\u0633\u062C\u0644 \u0627\u0644\u064A\u0648\u0645.\n\n\u062A\u062A\u0637\u0644\u0628 \u0627\u0644\u0628\u0637\u0627\u0642\u0627\u062A \u0627\u0644\u0622\u0646 \u0642\u0631\u0628\u0627\u0646\u0627\u064B \u0645\u0646 \u0627\u0644\u0637\u0627\u0642\u0629 \u0644\u0641\u062A\u062D \u0627\u0644\u062D\u062C\u0627\u0628 \u0645\u0631\u0629 \u0623\u062E\u0631\u0649. \u0647\u0644 \u0633\u062A\u062A\u0648\u0627\u0635\u0644 \u0627\u0644\u0622\u0646 \u0623\u0645 \u062A\u0639\u0648\u062F \u063A\u062F\u0627\u064B \u0639\u0646\u062F\u0645\u0627 \u062A\u063A\u0644\u0642 \u0643\u062A\u0644\u0629 UTC \u0627\u0644\u062A\u0627\u0644\u064A\u0629\u061F',
    fr: 'Vous avez \u00E9puis\u00E9 les 3 requ\u00EAtes sacr\u00E9es accord\u00E9es par le registre aujourd\'hui.\n\nLes cartes exigent d\u00E9sormais une offrande d\'\u00E9nergie pour entrouvrir le voile. Communiez-vous maintenant ou reviendrez-vous demain au prochain bloc UTC ?',
    bn: '\u0986\u09AA\u09A8\u09BF \u0986\u099C \u09B2\u09C7\u099C\u09BE\u09B0 \u09A6\u09CD\u09AC\u09BE\u09B0\u09BE \u09AA\u09CD\u09B0\u09A6\u09A4\u09CD\u09A4 \u09E9\u099F\u09BF \u09AA\u09AC\u09BF\u09A4\u09CD\u09B0 \u0985\u09A8\u09C1\u09B8\u09A8\u09CD\u09A7\u09BE\u09A8 \u09B6\u09C7\u09B7 \u0995\u09B0\u09C7\u099B\u09C7\u09A8\u0964\n\n\u09AA\u09B0\u09CD\u09A6\u09BE \u09AA\u09C1\u09A8\u09B0\u09BE\u09AF\u09BC \u0989\u09A8\u09CD\u09AE\u09CB\u099A\u09A8\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF \u0995\u09BE\u09B0\u09CD\u09A1\u0997\u09C1\u09B2\u09BF\u09A4\u09C7 \u09B6\u0995\u09CD\u09A4\u09BF\u09B0 \u09A8\u09C8\u09AC\u09C7\u09A6\u09CD\u09AF \u09AA\u09CD\u09B0\u09AF\u09BC\u09CB\u099C\u09A8\u0964 \u0986\u09AA\u09A8\u09BF \u0995\u09BF \u098F\u0996\u09A8\u0987 \u09AF\u09CB\u0997\u09BE\u09AF\u09CB\u0997 \u0995\u09B0\u09AC\u09C7\u09A8, \u09A8\u09BE\u0995\u09BF \u09AA\u09B0\u09AC\u09B0\u09CD\u09A4\u09C0 UTC \u09AC\u09CD\u09B2\u0995 \u09B8\u09BF\u09B2 \u09B9\u09B2\u09C7 \u09AB\u09BF\u09B0\u09C7 \u0986\u09B8\u09AC\u09C7\u09A8?',
    pt: 'Voc\u00EA esgotou as 3 consultas sagradas concedidas pelo registro hoje.\n\nAs cartas agora exigem uma oferenda de energia para abrir o v\u00E9u mais uma vez. Voc\u00EA comungar\u00E1 agora ou retornar\u00E1 amanh\u00E3 quando o pr\u00F3ximo bloco UTC selar?',
    ru: '\u0412\u044B \u0438\u0441\u0447\u0435\u0440\u043F\u0430\u043B\u0438 3 \u0441\u0432\u044F\u0449\u0435\u043D\u043D\u044B\u0445 \u0432\u043E\u043F\u0440\u043E\u0441\u0430, \u0434\u0430\u0440\u043E\u0432\u0430\u043D\u043D\u044B\u0445 \u0440\u0435\u0435\u0441\u0442\u0440\u043E\u043C \u043D\u0430 \u0441\u0435\u0433\u043E\u0434\u043D\u044F.\n\n\u041A\u043E\u043B\u043E\u0434\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442\u0441\u044F \u043F\u043E\u0434\u043D\u043E\u0448\u0435\u043D\u0438\u0435 \u044D\u043D\u0435\u0440\u0433\u0438\u0438, \u0447\u0442\u043E\u0431\u044B \u0432\u043D\u043E\u0432\u044C \u043F\u0440\u0438\u043E\u0442\u043A\u0440\u044B\u0442\u044C \u0437\u0430\u0432\u0435\u0441\u0443. \u0416\u0435\u043B\u0430\u0435\u0442\u0435 \u043F\u0440\u043E\u0434\u043E\u043B\u0436\u0438\u0442\u044C \u043E\u0431\u0449\u0435\u043D\u0438\u0435 \u0441\u0435\u0439\u0447\u0430\u0441 \u0438\u043B\u0438 \u0432\u0435\u0440\u043D\u0435\u0442\u0435\u0441\u044C \u0441 \u043D\u043E\u0432\u043E\u0439 \u044D\u043F\u043E\u0445\u043E\u0439 UTC?',
    id: 'Anda telah menghabiskan 3 pertanyaan suci yang diberikan buku besar hari ini.\n\nKartu-kartu kini membutuhkan persembahan energi untuk membuka tirai sekali lagi. Maukah Anda berkonsultasi sekarang, atau kembali besok saat blok UTC berikutnya disegel?',
  },
