  "sealed_consensus_note": {
    en: 'Today\'s block is permanently recorded in consensus. To consult the oracle further, cast a Spread below.',
    zh: '\u4ECA\u5929\u7684\u533A\u5757\u5DF2\u6C38\u4E45\u8BB0\u5F55\u5728\u5171\u8BC6\u4E2D\u3002\u5982\u9700\u8FDB\u4E00\u6B65\u5411\u795E\u8C15\u8BF7\u6559\uFF0C\u8BF7\u5728\u4E0B\u65B9\u8FDB\u884C\u724C\u9635\u63A8\u6F14\u3002',
    hi: '\u0906\u091C \u0915\u093E \u092C\u094D\u0932\u0949\u0915 \u0938\u094D\u0925\u093E\u092F\u0940 \u0930\u0942\u092A \u0938\u0947 \u0926\u0930\u094D\u091C \u0939\u0948\u0964 \u0906\u0917\u0947 \u092E\u093E\u0930\u094D\u0917\u0926\u0930\u094D\u0936\u0928 \u0915\u0947 \u0932\u093F\u090F \u0928\u0940\u091A\u0947 \u0938\u094D\u092A\u094D\u0930\u0947\u0921 \u0915\u0930\u0947\u0902\u0964',
    es: 'El bloque de hoy est\u00E1 registrado permanentemente. Para consultar m\u00E1s al or\u00E1culo, echa una Tirada abajo.',
    ar: '\u062A\u0645 \u062A\u0633\u062C\u064A\u0644 \u0643\u062A\u0644\u0629 \u0627\u0644\u064A\u0648\u0645 \u0628\u0634\u0643\u0644 \u062F\u0627\u0626\u0645 \u0641\u064A \u0627\u0644\u0625\u062C\u0645\u0627\u0639. \u0644\u0644\u0627\u0633\u062A\u0634\u0627\u0631\u0629 \u0628\u0634\u0643\u0644 \u0623\u0639\u0645\u0642\u060C \u0642\u0645 \u0628\u0639\u0645\u0644 \u0633\u062D\u0628 \u0623\u062F\u0646\u0627\u0647.',
    fr: 'Le bloc d\'aujourd\'hui est enregistr\u00E9 de mani\u00E8re permanente. Pour consulter davantage l\'oracle, effectuez un tirage ci-dessous.',
    bn: '\u0986\u099C\u0995\u09C7\u09B0 \u09AC\u09CD\u09B2\u0995\u099F\u09BF \u09B8\u09CD\u09A5\u09BE\u09AF\u09BC\u09C0\u09AD\u09BE\u09AC\u09C7 \u09B0\u09C7\u0995\u09B0\u09CD\u09A1 \u0995\u09B0\u09BE \u09B9\u09AF\u09BC\u09C7\u099B\u09C7\u0964 \u0986\u09B0\u0993 \u09AA\u09B0\u09BE\u09AE\u09B0\u09CD\u09B6\u09C7\u09B0 \u099C\u09A8\u09CD\u09AF \u09A8\u09C0\u099A\u09C7 \u09B8\u09CD\u09AA\u09CD\u09B0\u09C7\u09A1 \u0995\u09B0\u09C1\u09A8\u0964',
    pt: 'O bloco de hoje est\u00E1 registrado permanentemente no consenso. Para consultar mais o or\u00E1culo, lance uma Tirada abaixo.',
    ru: '\u0421\u0435\u0433\u043E\u0434\u043D\u044F\u0448\u043D\u0438\u0439 \u0431\u043B\u043E\u043A \u043D\u0430\u0432\u0435\u0447\u043D\u043E \u0432\u043F\u0438\u0441\u0430\u043D \u0432 \u043A\u043E\u043D\u0441\u0435\u043D\u0441\u0443\u0441. \u0427\u0442\u043E\u0431\u044B \u0432\u043E\u043F\u0440\u043E\u0441\u0438\u0442\u044C \u043E\u0440\u0430\u043A\u0443\u043B\u0430 \u0433\u043B\u0443\u0431\u0436\u0435, \u0441\u043E\u0432\u0435\u0440\u0448\u0438\u0442\u0435 \u0440\u0430\u0441\u043A\u043B\u0430\u0434 \u043D\u0438\u0436\u0435.',
    id: 'Blok hari ini dicatat secara permanen dalam konsensus. Untuk berkonsultasi lebih lanjut, tebarkan Spread di bawah.',
  },
