    ar: '\u062A\u0645 \u0625\u0644\u063A\u0627\u0621 \u0637\u0644\u0628 \u0627\u0644\u0627\u062A\u0635\u0627\u0644 \u0623\u0648 \u0631\u0641\u0636\u0647 \u0641\u064A \u0627\u0644\u0645\u062D\u0641\u0638\u0629. \u0627\u0646\u0642\u0631 \u0623\u062F\u0646\u0627\u0647 \u0644\u0625\u0639\u0627\u062F\u0629 \u0627\u0644\u0645\u062D\u0627\u0648\u0644\u0629.',
    fr: 'La demande de connexion a \u00E9t\u00E9 annul\u00E9e ou refus\u00E9e dans votre portefeuille. Touchez ci-dessous pour r\u00E9essayer.',
    bn: '\u09B8\u0982\u09AF\u09CB\u0997\u09C7\u09B0 \u0985\u09A8\u09C1\u09B0\u09CB\u09A7\u099F\u09BF \u09AC\u09BE\u09A4\u09BF\u09B2 \u09AC\u09BE \u09AA\u09CD\u09B0\u09A4\u09CD\u09AF\u09BE\u0996\u09CD\u09AF\u09BE\u09A8 \u0995\u09B0\u09BE \u09B9\u09AF\u09BC\u09C7\u099B\u09C7\u0964 \u09AA\u09C1\u09A8\u09B0\u09BE\u09AF\u09BC \u099A\u09C7\u09B7\u09CD\u099F\u09BE \u0995\u09B0\u09A4\u09C7 \u09A8\u09BF\u099A\u09C7 \u0986\u09B2\u09A4\u09CB \u099A\u09BE\u09AA\u09C1\u09A8\u0964',
    pt: 'A solicita\u00E7\u00E3o de conex\u00E3o foi cancelada ou recusada na sua carteira. Toque abaixo para tentar novamente.',
    ru: '\u0417\u0430\u043F\u0440\u043E\u0441 \u043D\u0430 \u043F\u043E\u0434\u043A\u043B\u044E\u0447\u0435\u043D\u0438\u0435 \u0431\u044B\u043B \u043E\u0442\u043A\u043B\u043E\u043D\u0435\u043D \u0438\u043B\u0438 \u0437\u0430\u043A\u0440\u044B\u0442 \u0432 \u043F\u0440\u0438\u043B\u043E\u0436\u0435\u043D\u0438\u0438 \u043A\u043E\u0448\u0435\u043B\u044C\u043A\u0430. \u041D\u0430\u0436\u043C\u0438\u0442\u0435 \u043A\u043D\u043E\u043F\u043A\u0443 \u043D\u0438\u0436\u0435, \u0447\u0442\u043E\u0431\u044B \u043F\u043E\u0432\u0442\u043E\u0440\u0438\u0442\u044C \u043F\u043E\u043F\u044B\u0442\u043A\u0443.',
    id: 'Permintaan koneksi dibatalkan atau ditolak di aplikasi dompet Anda. Ketuk di bawah untuk mencoba lagi.',
