    hi: 'भावनाओं में बहकर तेज़ लेन-देन और गलत आँकी गई प्रायोरिटी फीस ऐसे फोर्क लाती हैं जिन्हें टाला जा सकता था।',
    es: 'Operar al ritmo de las emociones y pagar mal las comisiones de prioridad lleva a bifurcaciones evitables.',
