    hi: 'वैल्यू उन्हीं तक पहुँचती है जो स्नैपशॉट से पहले लगातार हाज़िर रहते हैं।\n\nआज का आर्कटाइप: Airdrop ({o}).\n\n"{quote}"\n\n@SolanaMobile Seeker पर क्लॉक-इन स्ट्रीक का दिन {streak}.\n#Solana #ArkanaTarot #Seeker #ClockIn',
    es: 'El valor fluye hacia quienes aparecen con constancia antes del snapshot.\n\nArquetipo de hoy: Airdrop ({o}).\n\n"{quote}"\n\nRacha de {streak} días haciendo clock-in en @SolanaMobile Seeker.\n#Solana #ArkanaTarot #Seeker #ClockIn',
    ar: 'القيمة تتدفق إلى من يحضرون بانتظام قبل اللقطة.\n\nنموذج اليوم: Airdrop ({o}).\n\n"{quote}"\n\nاليوم {streak} من سلسلة التسجيل على @SolanaMobile Seeker.\n#Solana #ArkanaTarot #Seeker #ClockIn',
    fr: 'La valeur va à ceux qui sont là avec constance avant le snapshot.\n\nArchétype du jour : Airdrop ({o}).\n\n"{quote}"\n\nSérie de {streak} jours de clock-in sur @SolanaMobile Seeker.\n#Solana #ArkanaTarot #Seeker #ClockIn',
    bn: 'মূল্য তাদের কাছেই যায়, যারা স্ন্যাপশটের আগে নিয়মিত হাজির থাকে।\n\nআজকের আর্কিটাইপ: Airdrop ({o})।\n\n"{quote}"\n\n@SolanaMobile Seeker-এ ক্লক-ইন স্ট্রিকের দিন {streak}।\n#Solana #ArkanaTarot #Seeker #ClockIn',
    pt: 'O valor flui para quem aparece com constância antes do snapshot.\n\nArquétipo de hoje: Airdrop ({o}).\n\n"{quote}"\n\nSequência de {streak} dias de clock-in na @SolanaMobile Seeker.\n#Solana #ArkanaTarot #Seeker #ClockIn',
    ru: 'Ценность течёт к тем, кто стабильно приходит до снапшота.\n\nАрхетип дня: Airdrop ({o}).\n\n"{quote}"\n\nДень {streak} серии отметок на @SolanaMobile Seeker.\n#Solana #ArkanaTarot #Seeker #ClockIn',
    id: 'Nilai mengalir kepada mereka yang konsisten hadir sebelum snapshot.\n\nArketipe hari ini: Airdrop ({o}).\n\n"{quote}"\n\nStreak hari ke-{streak} clock-in di @SolanaMobile Seeker.\n#Solana #ArkanaTarot #Seeker #ClockIn',
