    ru: 'Децентрализованная взаимность. Дивиденды протокола закреплены на Алтаре Seeker: Airdrop ({o}).\n\n"{quote}"\n\nДень {streak}. Постоянство вознаграждается ончейн.\n#Solana #ArkanaTarot #Seeker',
