    ar: 'كل غصن ميت يُقطع يجعل السلسلة الأم أقوى.\n\nكشفت Arkana: The Hard Fork ({o}).\n\n"{quote}"\n\nإجماع اليوم {streak}. وداعًا للأعباء القديمة، وإلى الأمام نحو الكتلة الجديدة.\n#Solana #ArkanaTarot #Seeker',
