    bn: 'প্রতিটি মরা ডাল ছাঁটলে মূল চেইন আরও শক্ত হয়।\n\nArkana প্রকাশ করল: The Hard Fork ({o})।\n\n"{quote}"\n\nদিন {streak}-এর কনসেনসাস। পুরোনো বোঝা বিদায়, নতুন ব্লকের দিকে এগিয়ে।\n#Solana #ArkanaTarot #Seeker',
    pt: 'Cada galho morto podado deixa a chain raiz mais forte.\n\nArkana revelou: The Hard Fork ({o}).\n\n"{quote}"\n\nConsenso do dia {streak}. Fora a bagagem legada, rumo ao novo bloco.\n#Solana #ArkanaTarot #Seeker',
    ru: 'Каждая отсечённая мёртвая ветка делает основную цепь сильнее.\n\nArkana показала: The Hard Fork ({o}).\n\n"{quote}"\n\nДень {streak} консенсуса. Долой legacy-багаж, вперёд в новый блок.\n#Solana #ArkanaTarot #Seeker',
