    bn: 'অপরিবর্তনীয় স্টেট ট্রানজিশনের জন্য পুরোনো ফর্ককে মরতে দেওয়ার সাহস লাগে।\n\nবেদির কনসেনসাস: The Hard Fork ({o})।\n\n"{quote}"\n\nস্ট্রিকের দিন {streak}। মনের কোডবেস আপগ্রেড করছি।\n#Solana #ArkanaTarot #Seeker #ClockIn',
    pt: 'Transições de estado irreversíveis exigem coragem para deixar o fork antigo morrer.\n\nConsenso do Altar: The Hard Fork ({o}).\n\n"{quote}"\n\nSequência de {streak} dias. Atualizando o código mental.\n#Solana #ArkanaTarot #Seeker #ClockIn',
