    ar: 'حين يُبلغ ارتفاع الكتلة، يتحدث تاريخك على السلسلة أعلى من الكلمات.\n\nإجماع المذبح: Snapshot ({o}).\n\n"{quote}"\n\nاليوم {streak} من السلسلة على @SolanaMobile. مسؤول أمام السجل.\n#Solana #ArkanaTarot #Seeker #ClockIn',
    fr: 'Quand la hauteur de bloc est atteinte, ton historique on-chain parle plus fort que les mots.\n\nConsensus de l\'Autel : Snapshot ({o}).\n\n"{quote}"\n\nSérie de {streak} jours sur @SolanaMobile. Redevable au ledger.\n#Solana #ArkanaTarot #Seeker #ClockIn',
    bn: 'ব্লক হাইট যখন পৌঁছায়, আপনার অন-চেইন ইতিহাস কথার চেয়ে জোরে বলে।\n\nবেদির কনসেনসাস: Snapshot ({o})।\n\n"{quote}"\n\n@SolanaMobile-এ স্ট্রিকের দিন {streak}। লেজারের কাছে জবাবদিহি।\n#Solana #ArkanaTarot #Seeker #ClockIn',
    pt: 'Quando a altura do bloco chega, seu histórico on-chain fala mais alto que palavras.\n\nConsenso do Altar: Snapshot ({o}).\n\n"{quote}"\n\nSequência de {streak} dias na @SolanaMobile. Prestando contas ao ledger.\n#Solana #ArkanaTarot #Seeker #ClockIn',
    ru: 'Когда нужная высота блока достигнута, твоя ончейн-история говорит громче слов.\n\nКонсенсус Алтаря: Snapshot ({o}).\n\n"{quote}"\n\nДень {streak} серии на @SolanaMobile. Отчитываюсь перед леджером.\n#Solana #ArkanaTarot #Seeker #ClockIn',
    id: 'Saat block height tercapai, riwayat on-chain-mu berbicara lebih keras daripada kata-kata.\n\nKonsensus Altar: Snapshot ({o}).\n\n"{quote}"\n\nStreak hari ke-{streak} di @SolanaMobile. Bertanggung jawab pada ledger.\n#Solana #ArkanaTarot #Seeker #ClockIn',
