    ar: 'تكتمل الدورة. لم تعد اللامركزية تجربة: إنها آلة الحالة الكوكبية.\n\nإجماع Arkana: Mass Adoption ({o}).\n\n"{quote}"\n\nاليوم {streak} من السلسلة. لم نعد مبكرين؛ نحن هنا.\n#Solana #ArkanaTarot #Seeker #DeFAI',
    fr: 'Le cycle s\'accomplit. La décentralisation n\'est plus une expérience : c\'est la machine à états de la planète.\n\nConsensus d\'Arkana : Mass Adoption ({o}).\n\n"{quote}"\n\nSérie de {streak} jours. Nous ne sommes plus en avance ; nous sommes là.\n#Solana #ArkanaTarot #Seeker #DeFAI',
    bn: 'সাইকেল সম্পূর্ণ। বিকেন্দ্রীকরণ আর পরীক্ষা নয়: এটাই গোটা গ্রহের স্টেট মেশিন।\n\nArkana কনসেনসাস: Mass Adoption ({o})।\n\n"{quote}"\n\nস্ট্রিকের দিন {streak}। আমরা আর early নই; আমরা এখানে।\n#Solana #ArkanaTarot #Seeker #DeFAI',
    pt: 'O ciclo se completa. A descentralização não é mais um experimento: é a máquina de estados do planeta.\n\nConsenso de Arkana: Mass Adoption ({o}).\n\n"{quote}"\n\nSequência de {streak} dias. Não somos mais cedo; já chegamos.\n#Solana #ArkanaTarot #Seeker #DeFAI',
    ru: 'Цикл завершается. Децентрализация больше не эксперимент, а планетарная стейт-машина.\n\nКонсенсус Arkana: Mass Adoption ({o}).\n\n"{quote}"\n\nДень {streak} серии. Мы уже не рано. Мы здесь.\n#Solana #ArkanaTarot #Seeker #DeFAI',
    id: 'Siklus pun tuntas. Desentralisasi bukan lagi eksperimen: ia adalah state machine planet ini.\n\nKonsensus Arkana: Mass Adoption ({o}).\n\n"{quote}"\n\nStreak hari ke-{streak}. Kita bukan lagi early; kita sudah di sini.\n#Solana #ArkanaTarot #Seeker #DeFAI',
