    fr: 'Les baleines n\'annoncent pas leurs mouvements sur Twitter. Elles laissent des traces dans les carnets d\'ordres.\n\nConsensus d\'Arkana : The Whale ({o}).\n\n"{quote}"\n\nJour {streak}. Je suis le smart money pendant que la foule court après le bruit.\n#Solana #ArkanaTarot #Seeker #DeFAI',
    bn: 'তিমিরা টুইটারে তাদের চাল ঘোষণা করে না। তারা অর্ডার বুকে পায়ের ছাপ রেখে যায়।\n\nArkana কনসেনসাস: The Whale ({o})।\n\n"{quote}"\n\nদিন {streak}। ভিড় যখন গোলমালের পেছনে, আমি স্মার্ট মানির পেছনে।\n#Solana #ArkanaTarot #Seeker #DeFAI',
