    ru: 'Киты не анонсируют свои ходы в Twitter. Они оставляют следы в стаканах.\n\nКонсенсус Arkana: The Whale ({o}).\n\n"{quote}"\n\nДень {streak}. Слежу за умными деньгами, пока толпа гонится за шумом.\n#Solana #ArkanaTarot #Seeker #DeFAI',
