interface LanguageContextType {
  language: LanguageCode;
  setLanguage: (lang: LanguageCode) => Promise<void>;
  t: (key: string, fallback?: string, params?: Record<string, string | number>) => string;
  hasChosenLanguage: boolean;
  isModalOpen: boolean;
  openLanguageModal: () => void;
  closeLanguageModal: () => void;
  currentOption: LanguageOption;
}

const STORAGE_KEY = '@arkana_selected_dialect_v1';
const CHOSEN_FLAG_KEY = '@arkana_dialect_consecrated_v1';

const LanguageContext = createContext<LanguageContextType>({} as LanguageContextType);

/** Language used by translate() outside React components (errors, services). */
let activeLanguage: LanguageCode = 'en';

/** t() for code outside React components. */
export function translate(key: string, fallback?: string, params?: Record<string, string | number>): string {
  return translateFor(activeLanguage, key, fallback, params);
}

/** t() for an explicit language, e.g. when a service receives the language as an argument. */
export function translateFor(
  language: LanguageCode,
  key: string,
  fallback?: string,
  params?: Record<string, string | number>
): string {
  const entry = TRANSLATIONS[key];
  let res = (entry && (entry[language] || entry['en'])) || fallback || key;
  if (params) {
    Object.entries(params).forEach(([pKey, pVal]) => {
      res = res.replace(new RegExp(`\\{${pKey}\\}`, 'g'), () => String(pVal));
    });
  }
  return res;
}

/**
 * Known English messages from the server, the wallet and payment services, mapped to translation keys.
 * Order matters: the first matching pattern wins.
 */
const ERROR_MESSAGES: Array<[RegExp, string]> = [
  [/^Connect your wallet first/i, 'err_connect_wallet'],
  [/sign in with your wallet again|Sign-in request expired|Wallet sign-in failed|Sign-in is unavailable/i, 'err_sign_in_again'],
  [/Already clocked in today/i, 'err_already_clocked_in'],
  [/no broken streak to repair/i, 'err_no_broken_streak'],
  [/Payment signature is required/i, 'err_payment_missing'],
  [/payment was already used/i, 'err_payment_used'],
  [/not found on-chain yet/i, 'err_payment_pending'],
  [/Payment transaction failed on-chain/i, 'err_payment_failed'],
  [/Payment transaction is too old/i, 'err_payment_old'],
  [/not signed by this wallet/i, 'err_payment_wrong_wallet'],
  [/Payment (memo|did not|deposited)/i, 'err_payment_invalid'],
  [/Too many requests/i, 'err_rate_limited'],
  [/Invalid wallet address/i, 'err_invalid_wallet'],
  [/Daily free allowance reached|Free daily readings require/i, 'err_quota_exhausted'],
  [/DEX|route|swap/i, 'err_swap_unavailable'],
  [/Treasury|SECURITY ALERT/i, 'err_treasury_unverified'],
  [/reject|denied|declined|cancel/i, 'err_user_rejected'],
  [/insufficient|0x1\b|Attempt to debit/i, 'err_insufficient_funds'],
  [/Network request failed|fetch failed|timeout|timed out|network error/i, 'err_network'],
  [/Transaction dropped|dropped before confirmation/i, 'err_tx_dropped'],
  [/Wallet connection required/i, 'err_wallet_required_seal'],
];

/** Translates a known English error message; unknown messages are returned as they are. */
export function localizeErrorText(message: string): string {
  const text = String(message || '');
  for (const [pattern, key] of ERROR_MESSAGES) {
    if (pattern.test(text)) return translate(key, text);
  }
  return text;
}

export function LanguageProvider({ children }: PropsWithChildren) {
  const [language, setLanguageState] = useState<LanguageCode>('en');
  activeLanguage = language;
  const [hasChosenLanguage, setHasChosenLanguage] = useState<boolean>(true);
  const [isModalOpen, setIsModalOpen] = useState<boolean>(false);

  useEffect(() => {
    (async () => {
      try {
        const stored = await AsyncStorage.getItem(STORAGE_KEY);
        const chosen = await AsyncStorage.getItem(CHOSEN_FLAG_KEY);
        if (stored && LANGUAGES.some((l) => l.code === stored)) {
          setLanguageState(stored as LanguageCode);
        }
        if (!chosen) {
          setHasChosenLanguage(false);
          setIsModalOpen(true);
        } else {
          setHasChosenLanguage(true);
        }
      } catch (e) {
        console.warn('Failed to load language preferences:', e);
      }
    })();
  }, []);

  const setLanguage = async (code: LanguageCode) => {
    try {
      setLanguageState(code);
      setHasChosenLanguage(true);
      setIsModalOpen(false);
      await AsyncStorage.setItem(STORAGE_KEY, code);
      await AsyncStorage.setItem(CHOSEN_FLAG_KEY, 'true');
    } catch (e) {
      console.warn('Failed to persist language:', e);
    }
  };

  const t = (key: string, fallback?: string, params?: Record<string, string | number>): string => {
    const entry = TRANSLATIONS[key];
    let res = (entry && (entry[language] || entry['en'])) || fallback || key;
    if (params) {
      Object.entries(params).forEach(([pKey, pVal]) => {
        res = res.replace(new RegExp(`\\{${pKey}\\}`, 'g'), () => String(pVal));
      });
    }
    return res;
  };

  const currentOption = LANGUAGES.find((l) => l.code === language) || LANGUAGES[0];

  return (
    <LanguageContext.Provider
      value={{
        language,
        setLanguage,
        t,
        hasChosenLanguage,
        isModalOpen,
        openLanguageModal: () => setIsModalOpen(true),
        closeLanguageModal: () => setIsModalOpen(false),
        currentOption,
      }}
    >
      {children}
    </LanguageContext.Provider>
  );
}

export function useLanguage() {
  const ctx = useContext(LanguageContext);
  if (!ctx) {
    throw new Error('useLanguage must be used within LanguageProvider');
  }
  return ctx;
}

export function localizePosition(pos: string | undefined, t: (key: string, fallback?: string) => string): string {
  if (!pos) return '';
  const clean = pos.trim().toLowerCase();
  if (clean.includes('daily consensus') || clean === 'daily consensus block') return t('daily_consensus_block', pos);
  if (clean.includes("today's consensus")) return t('pos_today_consensus', pos);
  if (clean === 'past') return t('pos_past', pos);
  if (clean === 'present') return t('pos_present', pos);
  if (clean.includes('next block')) return t('pos_next_block', pos);
  if (clean.includes('current state')) return t('pos_current_state', pos);
  if (clean.includes('main opportunity')) return t('pos_main_opportunity', pos);
  if (clean.includes('main obstacle')) return t('pos_main_obstacle', pos);
  if (clean.includes('hidden influence')) return t('pos_hidden_influence', pos);
  if (clean.includes('outcome if the current path') || clean.includes('outcome')) return t('pos_outcome_path', pos);
  if (clean.includes('north') || clean.includes('vision')) return t('pos_north', pos);
  if (clean.includes('south') || clean.includes('foundation')) return t('pos_south', pos);
  if (clean.includes('east') || clean.includes('action')) return t('pos_east', pos);
  if (clean.includes('west') || clean.includes('risk')) return t('pos_west', pos);
  return pos;
}

export function localizePositionHint(hint: string | undefined, t: (key: string, fallback?: string) => string): string {
  if (!hint) return '';
  const clean = hint.trim().toLowerCase();
  if (clean.includes('primary archetype governing today')) return t('daily_consensus_hint', hint);
  if (clean.includes('block that set the current chain')) return t('hint_past', hint);
  if (clean.includes('current state of the network')) return t('hint_present', hint);
  if (clean.includes('most probable next step')) return t('hint_next_block', hint);
  if (clean.includes('where you stand')) return t('hint_current_state', hint);
  if (clean.includes('strongest supportive force')) return t('hint_main_opportunity', hint);
  if (clean.includes('central challenge crossing')) return t('hint_main_obstacle', hint);
  if (clean.includes("undercurrent you don't see")) return t('hint_hidden_influence', hint);
  if (clean.includes('tendency if nothing changes')) return t('hint_outcome_path', hint);
  if (clean.includes('prevailing energy validating')) return t('hint_today_consensus', hint);
  if (clean.includes('overarching cycle')) return t('hint_north', hint);
  if (clean.includes('liquidity, security')) return t('hint_south', hint);
  if (clean.includes('execution vector')) return t('hint_east', hint);
  if (clean.includes('vulnerabilities, market fear')) return t('hint_west', hint);
  return hint;
}

export function localizeSuit(suit: string | undefined, _t?: (key: string, fallback?: string) => string): string {
  if (!suit) return '';
  // Suits remain in canonical English per design
  return suit;
}

export function localizeArcana(arcana: string | undefined, t: (key: string, fallback?: string) => string): string {
  if (!arcana) return '';
  const clean = arcana.trim().toLowerCase();
  if (clean === 'major') return t('arcana_major', 'MAJOR');
  if (clean === 'minor') return t('arcana_minor', 'MINOR');
  return arcana;
}

